local DUEL_BRECHA_BLOCK = 2451900557               -- _pos_telop02: the brecha / save block of the shot readout
local DUEL_PRIM_TOTAL = 1040868230                 -- num_br_total_at01: the plate's big number (rolls up)
-- every other number of the shot readout's objects (brecha / save percentages, the second total)
local DUEL_PRIMS_HIDDEN = {1219286211, 3517285753, 2795681263, 952508492, 1338052826, 3603448160, 1536362464,
  1502288020, 1883395192, 676188912, 2571853099, 2392932880, 3862398564}
local DUEL_LABEL_TEXT_NODE = 378327766             -- _text_cmd_back01
local DUEL_LABEL_PLATE_MESHES = {298211823 --[[_cmd_back_base01]], 2853207670 --[[_cmd_back_base01_add]]}
local DUEL_LABEL_KEYS = {"clean_hud.duel_dribble", "clean_hud.duel_defense", "clean_hud.duel_power_charge",
  "clean_hud.duel_power_block"}
local DUEL_LABEL_KEY_CRCS = {3358745513, 220596504, 3633359080, 1880800829}

local DUEL_SHOW_SECONDS = 2.5                      -- on screen, after the slide in
local DUEL_CLOSE_SECONDS = 0.35                    -- the slide out before the layers close
local DUEL_LABEL_SCALE = 0.9
local DUEL_LABEL_WIDE_CHARS = 9                    -- wider labels go on two lines (as «TOTAL / AT»), then shrink
local DUEL_LABEL_TWO_LINES_SCALE = 0.75            -- a two-line label's scale (of DUEL_LABEL_SCALE)
local DUEL_POLL_FRAMES = 3                         -- the result is asked every N frames while nothing is shown
local DUEL_LABEL_SNAP = 3                          -- px: a label this close to its slot is shown
local DUEL_PROBE_STEP = 100                        -- px the label layer moves while its offset is measured
local DUEL_PROBE_WAIT = 2                          -- frames between a probe move and its reading
local DUEL_LABEL_SETTLE = 1                        -- frames between a label move and the next correction

local duel = {state = "idle", seen = nil, poll = 0, timer = 0, result = nil, labels = {}, probe = nil,
  scale = nil, logs = 0}

local function DuelMenu(...)
  if type(funcLuaMenuCommand) ~= "function" then
    return nil
  end
  local r = table.pack(pcall(funcLuaMenuCommand, ...))
  if not r[1] then
    return nil
  end
  return table.unpack(r, 2, r.n)
end

local function DuelCommand(...)
  if type(funcLuaCommand) ~= "function" then
    return nil
  end
  local r = table.pack(pcall(funcLuaCommand, ...))
  if not r[1] then
    return nil
  end
  return table.unpack(r, 2, r.n)
end

local function DuelLog(...)
  if duel.logs >= 30 then
    return
  end
  duel.logs = duel.logs + 1
  DuelCommand(DUEL_LOG, "BETTERUI_DUEL_READOUT", ...)
end

local function DuelEnabled()
  local v = DuelCommand(DUEL_OPTION_GET, DUEL_OPTION_KEY)
  return v ~= 0 and v ~= false
end

local function DuelLabelText(label)
  local key = DUEL_LABEL_KEYS[label]
  if key == nil then
    return ""
  end
  local id = DuelCommand(DUEL_TEXT_ID, key)
  if type(id) ~= "number" or id == 0 then
    id = DUEL_LABEL_KEY_CRCS[label]
  end
  local s = DuelCommand(DUEL_TEXT_GET, id)
  return type(s) == "string" and s or ""
end

-- display width in Latin characters (a CJK character counts as two)
local function DuelTextWidth(s)
  local width = 0
  for ch in s:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
    width = width + (#ch >= 3 and 2 or 1)
  end
  return width
end

-- the label's text and scale: a label wider than DUEL_LABEL_WIDE_CHARS is split at the space nearest its middle (two
-- lines, like the retail «TOTAL AT» picture), and what is still too wide is scaled down
local function DuelLabelLayout(text)
  local scale = DUEL_LABEL_SCALE
  local width = DuelTextWidth(text)
  if width <= DUEL_LABEL_WIDE_CHARS then
    return text, scale
  end
  local best, best_gap = nil, nil
  for at in text:gmatch("() ") do
    local gap = math.abs(DuelTextWidth(text:sub(1, at - 1)) - width / 2)
    if best_gap == nil or gap < best_gap then
      best, best_gap = at, gap
    end
  end
  if best ~= nil then
    local first, second = text:sub(1, best - 1), text:sub(best + 1)
    text = first .. "\n" .. second
    width = math.max(DuelTextWidth(first), DuelTextWidth(second))
    scale = scale * DUEL_LABEL_TWO_LINES_SCALE
  end
  if width > DUEL_LABEL_WIDE_CHARS then
    scale = scale * DUEL_LABEL_WIDE_CHARS / width
  end
  return text, scale
end

local function DuelSetNumber(layer, value)
  local index = DuelMenu(DUEL_CMD.PRIM_INDEX, layer, 0, DUEL_PRIM_TOTAL)
  if index ~= nil then
    DuelMenu(DUEL_CMD.PRIM_VALUE, layer, 0, index, value)
  end
end

-- a plate just opened: the shot readout's own setup, without its picture label, portrait and brecha / save block
local function DuelSetupPlate(plate, value)
  local layer = plate.layer
  DuelMenu(DUEL_CMD.SUSPEND, layer, 0, false)
  for _, prim in ipairs(DUEL_PRIMS_HIDDEN) do
    DuelMenu(DUEL_CMD.PRIM_VISIBLE, layer, 0, prim, false)
  end
  DuelMenu(DUEL_CMD.PRIM_VISIBLE, layer, 0, DUEL_PRIM_TOTAL, true)
  DuelSetNumber(layer, value)
  DuelMenu(DUEL_CMD.NODE_VISIBLE, layer, DUEL_BRECHA_BLOCK, false)
  DuelMenu(DUEL_CMD.NODE_VISIBLE, layer, plate.hide, false)
  DuelMenu(DUEL_CMD.NODE_VISIBLE, layer, plate.keep, true)
  DuelMenu(DUEL_CMD.MESH_VISIBLE, layer, plate.label, false, 0)
  DuelMenu(DUEL_CMD.MESH_VISIBLE, layer, plate.portrait, false, 0)
  DuelMenu(DUEL_CMD.ANIME, layer, 0, DUEL_ANIME_OPEN, 0, DUEL_ANIME_COMMON)
  DuelMenu(DUEL_CMD.ANIME, layer, 0, DUEL_ANIME_OPEN, 0, plate.anime)
end

local function DuelHideLabel(i)
  DuelMenu(DUEL_CMD.VISIBLE, DUEL_LAYER_LABEL, i, false)
  duel.labels[i + 1] = nil
end

local function DuelGlobal(layer, index, node)
  local x, y = DuelMenu(DUEL_CMD.GLOBAL_POS, layer, index, node)
  if type(x) ~= "number" or type(y) ~= "number" then
    return nil
  end
  return x, y
end

-- the label layer's position -> its text node's global position: global = position * scale + offset, per axis. Measured
-- once per HUD with label 0 (hidden): placed at 0, then moved by DUEL_PROBE_STEP, each reading DUEL_PROBE_WAIT frames
-- after the move. Called once per frame; true when known.
local function DuelProbe()
  if duel.scale ~= nil then
    return duel.scale ~= false
  end
  local p = duel.probe
  if p == nil then
    duel.probe = {step = 0, wait = DUEL_PROBE_WAIT}
    DuelMenu(DUEL_CMD.POS, DUEL_LAYER_LABEL, 0, 0, 0, 0)
    return false
  end
  if p.wait > 0 then
    p.wait = p.wait - 1
    return false
  end
  local x, y = DuelGlobal(DUEL_LAYER_LABEL, 0, DUEL_LABEL_TEXT_NODE)
  if x == nil then
    duel.scale = false
    DuelLog("label: no global position for its text node: labels off")
    return false
  end
  if p.step == 0 then
    p.x0, p.y0, p.step, p.wait = x, y, 1, DUEL_PROBE_WAIT
    DuelMenu(DUEL_CMD.POS, DUEL_LAYER_LABEL, DUEL_PROBE_STEP, DUEL_PROBE_STEP, 0, 0)
    return false
  end
  local sx, sy = (x - p.x0) / DUEL_PROBE_STEP, (y - p.y0) / DUEL_PROBE_STEP
  if math.abs(sx) < 0.1 or math.abs(sy) < 0.1 then
    duel.scale = false
    DuelLog("label: position does not move its text node (", sx, sy, "): labels off")
    return false
  end
  duel.scale = {x = sx, y = sy, ox = p.x0, oy = p.y0}
  DuelLog("label: position scale", string.format("%.3f %.3f", sx, sy), "origin", string.format("%.1f %.1f", p.x0, p.y0))
  return true
end

-- keep label i on its plate's label slot: left edge on the hidden picture label, centre line on the plate's band. The
-- position is corrected from the text node's global position every DUEL_LABEL_SETTLE frames (the reading follows a
-- move a frame later); the label shows once it is within DUEL_LABEL_SNAP px of its slot.
local function DuelPlaceLabel(i, plate, text)
  local k = duel.scale
  if type(k) ~= "table" then
    return
  end
  local tx = DuelGlobal(plate.layer, 0, plate.label)
  local _, ty = DuelGlobal(plate.layer, 0, plate.slide)
  if tx == nil or ty == nil then
    DuelHideLabel(i)
    return
  end
  local label = duel.labels[i + 1]
  if label == nil then
    local shown_text, scale = DuelLabelLayout(text)
    for _, mesh in ipairs(DUEL_LABEL_PLATE_MESHES) do
      DuelMenu(DUEL_CMD.MESH_VISIBLE, DUEL_LAYER_LABEL, mesh, false, i)
    end
    DuelMenu(DUEL_CMD.TEXT, DUEL_LAYER_LABEL, DUEL_LABEL_TEXT_NODE, shown_text, i)
    DuelMenu(DUEL_CMD.SCALE, DUEL_LAYER_LABEL, scale, scale, 1, i)
    -- first guess from the measured offset; the scale moves the text node a little, corrected below
    label = {x = (tx - k.ox) / k.x, y = (ty - k.oy) / k.y, shown = false, wait = DUEL_LABEL_SETTLE}
    duel.labels[i + 1] = label
    DuelMenu(DUEL_CMD.POS, DUEL_LAYER_LABEL, label.x, label.y, 0, i)
    return
  end
  if label.wait > 0 then
    label.wait = label.wait - 1
    return
  end
  local cx, cy = DuelGlobal(DUEL_LAYER_LABEL, i, DUEL_LABEL_TEXT_NODE)
  if cx == nil then
    DuelHideLabel(i)
    return
  end
  local ex, ey = tx - cx, ty - cy
  if not label.shown and math.abs(ex) <= DUEL_LABEL_SNAP and math.abs(ey) <= DUEL_LABEL_SNAP then
    label.shown = true
    DuelMenu(DUEL_CMD.VISIBLE, DUEL_LAYER_LABEL, i, true)
  end
  if math.abs(ex) > 0.5 or math.abs(ey) > 0.5 then
    label.x = label.x + ex / k.x
    label.y = label.y + ey / k.y
    label.wait = DUEL_LABEL_SETTLE
    DuelMenu(DUEL_CMD.POS, DUEL_LAYER_LABEL, label.x, label.y, 0, i)
  end
end

local function DuelCloseAll()
  for i = 0, 1 do
    DuelHideLabel(i)
  end
  DuelMenu(DUEL_CMD.CLOSE, DUEL_LAYER_SELF)
  DuelMenu(DUEL_CMD.CLOSE, DUEL_LAYER_ENEMY)
  duel.state = "idle"
  duel.result = nil
end

local function DuelStart(result)
  duel.result = result
  duel.state = "opening"
  duel.timer = 0
  duel.labels = {}
  DuelMenu(DUEL_CMD.OPEN, DUEL_LAYER_SELF)
  DuelMenu(DUEL_CMD.OPEN, DUEL_LAYER_ENEMY)
  if DuelMenu(DUEL_CMD.IS_OPEN, DUEL_LAYER_LABEL) ~= true then
    DuelMenu(DUEL_CMD.OPEN_ARRAY, DUEL_LAYER_LABEL)
  end
  DuelLog("shown", result.left_power, result.left_label, "vs", result.right_power, result.right_label)
end

local function DuelPoll()
  duel.poll = duel.poll + 1
  if duel.poll < DUEL_POLL_FRAMES then
    return
  end
  duel.poll = 0
  if duel.seen == nil then
    local current = DuelCommand(DUEL_READOUT_CMD, -1)
    if type(current) == "number" then
      duel.seen = current
    end
    return
  end
  local sequence, left_power, left_label, right_power, right_label = DuelCommand(DUEL_READOUT_CMD, duel.seen)
  if type(sequence) ~= "number" or sequence <= duel.seen then
    return
  end
  duel.seen = sequence
  if type(left_power) ~= "number" or type(right_power) ~= "number" or not DuelEnabled() then
    return
  end
  DuelStart({left_power = left_power, left_label = left_label, right_power = right_power, right_label = right_label,
    left_text = DuelLabelText(left_label), right_text = DuelLabelText(right_label)})
end

function BetterUIDuelReadout_Step()
  if duel.state == "idle" then
    DuelPoll()
    return
  end
  local dt = DuelCommand(DUEL_FRAME_SECONDS)
  if type(dt) ~= "number" then
    dt = 1 / 60
  end
  if duel.state == "opening" then
    if DuelMenu(DUEL_CMD.IS_OPEN, DUEL_LAYER_SELF) ~= true or DuelMenu(DUEL_CMD.IS_OPEN, DUEL_LAYER_ENEMY) ~= true then
      duel.timer = duel.timer + dt
      if duel.timer > 2 then
        DuelLog("plates did not open: skipped")
        DuelCloseAll()
      end
      return
    end
    duel.state = "shown"
    duel.timer = 0
  end
  duel.timer = duel.timer + dt
  local result = duel.result
  local labels_ready = DuelMenu(DUEL_CMD.IS_OPEN, DUEL_LAYER_LABEL) == true
    and DuelMenu(DUEL_CMD.IS_LOADING, DUEL_LAYER_LABEL) ~= true
  if labels_ready and duel.state == "shown" and DuelProbe() then
    DuelPlaceLabel(0, DUEL_PLATES[1], result.left_text)
    DuelPlaceLabel(1, DUEL_PLATES[2], result.right_text)
  end
  if duel.state == "shown" and duel.timer >= DUEL_SHOW_SECONDS then
    duel.state = "closing"
    duel.timer = 0
    DuelHideLabel(0)
    DuelHideLabel(1)
    for _, plate in ipairs(DUEL_PLATES) do
      DuelMenu(DUEL_CMD.ANIME, plate.layer, 0, DUEL_ANIME_OPEN, 2, plate.anime)
    end
  elseif duel.state == "closing" and duel.timer >= DUEL_CLOSE_SECONDS then
    DuelCloseAll()
  end
end

local BetterUIDuelReadout_previousOpenLayer = OnOpenLayer
function OnOpenLayer(a1, a2, ...)
  local r = {n = 0}
  if type(BetterUIDuelReadout_previousOpenLayer) == "function" then
    r = table.pack(BetterUIDuelReadout_previousOpenLayer(a1, a2, ...))
  end
  if duel.result ~= nil then
    if a1 == DUEL_LAYER_SELF then
      pcall(DuelSetupPlate, DUEL_PLATES[1], duel.result.left_power)
    elseif a1 == DUEL_LAYER_ENEMY then
      pcall(DuelSetupPlate, DUEL_PLATES[2], duel.result.right_power)
    end
  end
  if a1 == DUEL_LAYER_LABEL then
    pcall(DuelMenu, DUEL_CMD.VISIBLE, DUEL_LAYER_LABEL, a2 or 0, false)
  end
  return table.unpack(r, 1, r.n)
end

local BetterUIDuelReadout_previousInit = OnInit
function OnInit(...)
  local r = {n = 0}
  if type(BetterUIDuelReadout_previousInit) == "function" then
    r = table.pack(BetterUIDuelReadout_previousInit(...))
  end
  duel = {state = "idle", seen = nil, poll = 0, timer = 0, result = nil, labels = {}, probe = nil, scale = nil,
    logs = duel.logs}
  return table.unpack(r, 1, r.n)
end

local BetterUIDuelReadout_previousStep = Step
function Step(...)
  local r = {n = 0}
  if type(BetterUIDuelReadout_previousStep) == "function" then
    r = table.pack(BetterUIDuelReadout_previousStep(...))
  end
  local ok, err = pcall(BetterUIDuelReadout_Step)
  if not ok then
    DuelLog("step error", tostring(err))
    pcall(DuelCloseAll)
  end
  return table.unpack(r, 1, r.n)
end
